function messagePreview(text){modal(`<div class="modal-content"><h2>Revise sua mensagem.</h2><label>Mensagem<textarea id="message-text" rows="6">${esc(text)}</textarea></label><p>Envio manual. Nenhuma mensagem será enviada automaticamente.</p><button class="btn" id="message-copy">Copiar mensagem</button>${data.settings.whatsapp?'<button class="btn secondary" id="message-open">Abrir WhatsApp</button>':'<p class="fine">WhatsApp real não configurado nesta demonstração.</p>'}</div>`);document.querySelector('#message-copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#message-text').value);toast('Mensagem copiada.')}catch{toast('Selecione e copie o texto da mensagem.')}};document.querySelector('#message-open')?.addEventListener('click',()=>window.open(`https://wa.me/${data.settings.whatsapp.replace(/\D/g,'')}?text=${encodeURIComponent(document.querySelector('#message-text').value)}`,'_blank','noopener'));}
function openBooking(interest='',professional='',focus=''){let step=0;const listNames=getList().map(id=>data.treatments.find(t=>t.id===id)?.name).filter(Boolean);const values={focus,list:listNames,interest:interest||visibleTreatments()[0]?.name||'Avaliação',region:'Rosto',experience:'Primeira avaliação',period:'Manhã',name:'Cliente Exemplo',phone:'11900000000',date:'',time:'09:00',professional:professional||data.professionals.find(p=>p.active)?.id||'p1'};const labels=['Seu objetivo','Região de interesse','Sua experiência','Melhor período','Data, horário e dados','Revisar solicitação'];function draw(){const options=(key,items)=>`<div class="choice-grid">${items.map(v=>`<label class="choice"><input type="radio" name="${key}" value="${esc(v)}" ${values[key]===v?'checked':''}>${esc(v)}</label>`).join('')}</div>`;let body='';if(step===0)body=`<label>Qual cuidado quer conhecer?<select name="interest">${visibleTreatments().map(t=>`<option ${values.interest===t.name?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`;if(step===1)body=options('region',['Rosto','Corpo','Bem-estar','Quero conversar']);if(step===2)body=options('experience',['Primeira avaliação','Já conheço cuidados estéticos','Prefiro conversar na avaliação']);if(step===3)body=options('period',['Manhã','Tarde']);if(step===4)body=`<p class="notice">Use somente dados fictícios. Esta solicitação fica neste navegador.</p><div class="form-grid"><label>Data<input required type="date" name="date" min="${new Date().toLocaleDateString('en-CA')}" value="${values.date}"></label><label>Profissional<select name="professional">${data.professionals.filter(p=>p.active).map(p=>`<option value="${p.id}" ${values.professional===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><fieldset class="slots"><legend>Horários livres · ${esc(values.period)}</legend><div id="slot-list" aria-live="polite"></div></fieldset><label>Nome fictício<input required name="name" minlength="2" maxlength="80" value="${esc(values.name)}"></label><label>WhatsApp fictício<input required name="phone" pattern="[0-9 \\(\\)\\+\\-]{10,18}" value="${esc(values.phone)}"></label><label class="checkbox"><input type="checkbox" required name="consent" ${values.consent?'checked':''}>Entendo que esta é uma simulação e usarei dados fictícios.</label>`;if(step===5)body=`<dl class="review-list"><dt>Nome</dt><dd>${esc(values.name)}</dd><dt>Cuidado</dt><dd>${esc(values.interest)}</dd><dt>Preferência</dt><dd>${esc(values.region)} · ${esc(values.period)}</dd><dt>Data e hora</dt><dd>${esc(prettyDate(values.date))} às ${esc(values.time)}</dd><dt>Profissional</dt><dd>${esc(data.professionals.find(p=>p.id===values.professional)?.name)}</dd>${values.focus?`<dt>Foco no rosto</dt><dd>${esc(values.focus)}</dd>`:''}${values.list.length?`<dt>Minha lista</dt><dd>${esc(values.list.join(', '))}</dd>`:''}</dl><p class="notice">A solicitação é demonstrativa. Não confirma atendimento real.</p>`;modal(`<div class="modal-content booking"><p class="eyebrow">AVALIAÇÃO DEMONSTRATIVA · ${step+1} DE 6</p><div class="step-progress"><span style="width:${(step+1)/6*100}%"></span></div><h2>${labels[step]}</h2><form id="booking-form">${body}<p class="form-error" role="alert"></p><div class="modal-actions">${step?'<button type="button" class="btn secondary" id="booking-back">Voltar</button>':''}<button class="btn">${step===5?'Confirmar solicitação':'Continuar'}</button></div></form></div>`,'Solicitar avaliação');if(step===4){const form=document.querySelector('#booking-form');const drawSlots=()=>{const date=form.elements.date.value,professional=form.elements.professional.value,list=document.querySelector('#slot-list');if(!date){list.innerHTML='<p class="fine">Escolha uma data para ver os horários livres.</p>';return}const slots=availability(load(),{date,period:values.period,professional});if(!slots.length){list.innerHTML=`<p class="fine">${new Date(date+'T12:00:00').getDay()===0?'Aos domingos a clínica não abre.':'Sem atendimento neste período: aos sábados atendemos só pela manhã.'} Escolha outra data ou volte e troque o período.</p>`;return}const first=slots.find(s=>s.free&&s.time===values.time)||slots.find(s=>s.free);list.innerHTML=`<div class="slot-grid">${slots.map(s=>`<label class="slot ${s.free?'':'busy'}"><input type="radio" name="time" value="${s.time}" ${s.free?'':'disabled'} ${first?.time===s.time?'checked':''}><span>${s.time}</span>${s.free?'':'<small>indisponível</small>'}</label>`).join('')}</div>${first?'':'<p class="fine">Nenhum horário livre neste período com esta profissional. Tente outra data ou profissional.</p>'}`};form.elements.date.addEventListener('change',drawSlots);form.elements.professional.addEventListener('change',drawSlots);drawSlots();}document.querySelector('#booking-back')?.addEventListener('click',()=>{Object.assign(values,Object.fromEntries(new FormData(document.querySelector('#booking-form'))));step--;draw()});document.querySelector('#booking-form').onsubmit=e=>{e.preventDefault();if(step===4&&!new FormData(e.target).get('time')){document.querySelector('.form-error').textContent='Escolha um horário livre para continuar.';return}Object.assign(values,Object.fromEntries(new FormData(e.target)),{focus:values.focus,list:values.list});if(step===3)values.time=values.period==='Manhã'?'09:00':'14:00';if(step<5){step++;draw();return}try{book(values);modal(`<div class="modal-content success"><span class="success-mark">✓</span><p class="eyebrow">SOLICITAÇÃO REGISTRADA</p><h2>Seu cuidado começa na escuta.</h2><p>${esc(prettyDate(values.date))} às ${esc(values.time)} · ${esc(values.interest)}. O contato e o agendamento fictícios já estão no painel deste navegador.</p><div class="success-actions"><button class="btn" id="booking-message">Revisar mensagem</button><button class="btn secondary" id="booking-ics">Adicionar à minha agenda</button></div><a class="text-link" href="admin.html">Ver no painel</a></div>`);if(!calm())celebrate();document.querySelector('#booking-ics').onclick=()=>{download('avaliacao-lumea.ics',ics({title:`Avaliação ${data.settings.name} · ${values.interest}`,date:values.date,time:values.time,description:`Solicitação demonstrativa com ${data.professionals.find(p=>p.id===values.professional)?.name||'profissional'}. Não confirma atendimento real.`,location:data.settings.address}),'text/calendar;charset=utf-8');toast('Arquivo de agenda gerado.')};document.querySelector('#booking-message').onclick=()=>messagePreview(`Olá! Sou ${values.name} (demonstração). Solicitei avaliação para ${values.interest}, em ${values.date} às ${values.time}.`)}catch(err){document.querySelector('.form-error').textContent=err.message}};}draw();}
/* Quiz "Por onde começar?": três perguntas, até três sugestões para levar à avaliação. */
const quiz=[
 {q:'O que mais te incomoda hoje?',key:'concern',options:[['textura','Textura e poros','✦'],['manchas','Manchas e tom irregular','◐'],['linhas','Linhas e firmeza do rosto','◠'],['acne','Acne ou oleosidade','◦'],['corpo','Celulite e flacidez','◇'],['contorno','Medidas e contorno','◯'],['pelos','Pelos','≈'],['posop','Recuperação pós-cirurgia','✚']]},
 {q:'Você já fez algum cuidado estético?',key:'experience',options:[['nunca','Nunca fiz nada','·'],['leve','Já fiz cuidados leves','··'],['tecnologia','Já fiz tecnologias','···']]},
 {q:'Quanto tempo de recuperação cabe na sua rotina?',key:'downtime',options:[['nenhum','Nenhum: quero voltar à rotina na hora','0'],['curto','Um ou dois dias, tudo bem','1–2'],['conversa','Prefiro decidir na avaliação','?']]}];
const quizMap={textura:['Limpeza de pele','Peeling superficial','Microagulhamento'],manchas:['Tratamento para manchas','Luz pulsada','Laser'],linhas:['Rejuvenescimento','Radiofrequência','Tecnologia de rejuvenescimento'],acne:['Tratamento para acne','Limpeza de pele','Peeling superficial'],corpo:['Tratamento para celulite','Tratamento para flacidez','Radiofrequência'],contorno:['Modelagem corporal','Gordura localizada','Drenagem linfática'],pelos:['Depilação a laser','Luz pulsada'],posop:['Cuidados pós-operatórios','Drenagem linfática']};
const quizWhy={'Limpeza de pele':'Primeiro passo para quase toda pele: tira o excesso e mostra o que realmente precisa de atenção.','Peeling superficial':'Renova a camada mais externa e ajuda na textura.','Microagulhamento':'Estimula a pele a se renovar; costuma pedir um ou dois dias de vermelhidão.','Tratamento para manchas':'Protocolo pensado para tom irregular, sempre com proteção solar no plano.','Luz pulsada':'Tecnologia que atua em manchas e vasinhos, indicada após avaliação do fototipo.','Laser':'Recurso preciso para alguns tipos de mancha; a indicação depende da sua pele.','Rejuvenescimento':'Combina cuidados para viço e linhas finas, sem mudar a sua expressão.','Radiofrequência':'Calor controlado que trabalha a firmeza, sem tempo de recuperação.','Tecnologia de rejuvenescimento':'LED e outras luzes para viço, confortável e sem recuperação.','Tratamento para acne':'Controle de oleosidade e inflamação, com orientação para casa.','Tratamento para celulite':'Protocolo corporal que combina técnicas manuais e tecnologia.','Tratamento para flacidez':'Foco em firmeza da pele do corpo, em sessões espaçadas.','Modelagem corporal':'Plano combinado para medidas, acompanhado com fotos e fita a cada etapa.','Gordura localizada':'Tecnologia para regiões específicas, como complemento de hábitos.','Drenagem linfática':'Alívio de inchaço e sensação de leveza, gostosa até como primeira experiência.','Depilação a laser':'Redução progressiva dos pelos, com sessões mensais.','Cuidados pós-operatórios':'Acompanhamento delicado, alinhado com a orientação do seu cirurgião.','Hidratação facial':'Cuidado confortável que devolve viço e não pede recuperação.','Protocolos faciais personalizados':'Combinação montada para você depois da avaliação.'};
function quizResult(a){let names=[...(quizMap[a.concern]||[])];if(a.downtime==='nenhum')names=names.filter(n=>!['Microagulhamento','Peeling superficial','Laser'].includes(n));if(a.experience==='nunca'){const gentle=['textura','manchas','linhas','acne'].includes(a.concern)?'Hidratação facial':['corpo','contorno','posop'].includes(a.concern)?'Drenagem linfática':'';if(gentle&&!names.includes(gentle))names.unshift(gentle)}if(names.length<2)names.push(['textura','manchas','linhas','acne'].includes(a.concern)?'Protocolos faciais personalizados':'Drenagem linfática');return [...new Set(names)].map(n=>data.treatments.find(t=>t.name===n&&t.visible)).filter(Boolean).slice(0,3);}
function openQuiz(){let step=0;const answers={};const draw=()=>{if(step>=quiz.length)return showResult();const item=quiz[step];modal(`<div class="modal-content quiz"><p class="eyebrow">POR ONDE COMEÇAR · ${step+1} DE ${quiz.length}</p><div class="step-progress"><span style="width:${(step+1)/(quiz.length+1)*100}%"></span></div><h2>${item.q}</h2><div class="quiz-grid ${item.options.length>4?'many':''}">${item.options.map(([v,l,ic])=>`<button class="quiz-opt ${answers[item.key]===v?'on':''}" data-v="${v}"><span class="qi" aria-hidden="true">${ic}</span>${l}</button>`).join('')}</div><div class="modal-actions">${step?'<button class="btn secondary" id="quiz-back">Voltar</button>':'<span></span>'}<p class="fine">Escolha uma opção para continuar.</p></div></div>`,'Por onde começar');document.querySelectorAll('.quiz-opt').forEach(b=>b.onclick=()=>{answers[item.key]=b.dataset.v;b.classList.add('on');setTimeout(()=>{step++;draw()},calm()?0:220)});document.querySelector('#quiz-back')?.addEventListener('click',()=>{step--;draw()})};
 const showResult=()=>{const picks=quizResult(answers),label=quiz[0].options.find(o=>o[0]===answers.concern)?.[1]||'';modal(`<div class="modal-content quiz quiz-result"><p class="eyebrow">SUGESTÃO PARA A SUA AVALIAÇÃO</p><div class="step-progress"><span style="width:100%"></span></div><h2>Para <em>${esc(label.toLowerCase())}</em>, um bom começo é:</h2><ol class="quiz-picks">${picks.map((t,i)=>`<li>${image(t.image,'','',false,'120px')}<div><small>0${i+1} · ${esc(t.category)} · ${esc(t.duration)} min</small><b>${esc(t.name)}</b><p>${esc(quizWhy[t.name]||t.summary)}</p><button class="text-link" data-detail="${t.id}">Ver detalhes</button></div></li>`).join('')}</ol><p class="notice">É uma sugestão para conversar na avaliação, não uma indicação. Quem define o protocolo é a profissional, depois de ver a sua pele.</p><div class="modal-actions-row"><button class="btn" id="quiz-book">Agendar com este resultado</button><button class="btn secondary" id="quiz-save">♡ Salvar na minha lista</button><button class="text-link" id="quiz-again">Refazer</button></div></div>`,'Sugestão');
  document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>treatmentDetail(b.dataset.detail));document.querySelector('#quiz-book').onclick=()=>openBooking(picks[0]?.name||'','',`Quiz: ${label}`);document.querySelector('#quiz-save').onclick=e=>{const list=getList();setList([...new Set([...list,...picks.map(t=>t.id)])]);flyTo(e.currentTarget,document.querySelector('#list-open'));renderTreatments();refreshList(true);e.currentTarget.textContent='♥ Salvos na lista';toast('Sugestões salvas na sua lista.')};document.querySelector('#quiz-again').onclick=()=>{step=0;Object.keys(answers).forEach(k=>delete answers[k]);draw()};};draw();}
/* Pequeno brilho champanhe na confirmação. */
function celebrate(){const mark=document.querySelector('.success-mark');if(!mark)return;for(let i=0;i<14;i++){const s=document.createElement('i');s.className='spark';const a=i/14*Math.PI*2,d=48+Math.random()*34;s.style.setProperty('--x',Math.cos(a)*d+'px');s.style.setProperty('--y',Math.sin(a)*d+'px');s.style.animationDelay=Math.random()*120+'ms';mark.append(s);setTimeout(()=>s.remove(),1300)}}
window.addEventListener('pointermove',e=>{if(drag)drag.strip.scrollLeft=drag.left-(e.clientX-drag.x)},{passive:true});window.addEventListener('pointerup',()=>{if(drag){drag.strip.classList.remove('dragging');drag=null}});
window.addEventListener('storage',e=>{if(e.key==='lumea-demo-v1'&&!document.querySelector('.modal'))render()});render();
